import { task, taskDefinition } from './task.mjs';
import { decisionBody } from './moderation.mjs';

// Both paths use the same rubric, inputs and normalized output contract.
// Jev's typed Decisions adapter is prepared in advance, not generated by Pi.
export async function classify(email, model, options = {}) {
  const scenario = options.task ? taskDefinition(options.task) : task;
  if (!scenario.models.some(m => m.id === model)) throw new Error('Model is not available for this task.');
  if(scenario.workflow) return scenario.runWorkflow(email,scenario.models.find(m=>m.id===model),(messages,stepModel,responseFormat,maxTokens=350,stepOptions={})=>infer(messages,stepModel,{...options,maxTokens,responseFormat,reasoning:scenario.reasoning,...stepOptions}));
  const decisions = model === 'typesafe/jev-1.13';
  return infer([{role:'system',content:scenario.rubric},{role:'user',content:email}],model,options,decisions?decisionBody(email):null);
}
async function infer(messages,model,options,decision=null) {
  const decisions=!!decision;
  const endpoint = options.endpoint ?? (decisions ? process.env.DEMO_DECISIONS_URL ?? 'https://openrouter.ai/api/alpha/decisions' : process.env.DEMO_INFERENCE_URL ?? 'https://openrouter.ai/api/v1/chat/completions');
  const key = options.key ?? process.env.DEMO_PROXY_TOKEN ?? process.env.OPENROUTER_API_KEY;
  if (!key) throw new Error('Inference is not configured.');
  const start = performance.now();
  const response = await fetch(endpoint, {
    method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${key}` },
    signal: AbortSignal.timeout(45000),
    body: JSON.stringify(decision ?? { model, temperature: 0, max_tokens: options.maxTokens ?? 200, stream: false,
      messages,...(options.reasoning?{reasoning:options.reasoning}:{}),
      ...(options.responseFormat===null?{}:{response_format:options.responseFormat ?? {type:'json_object'}}), provider: { require_parameters: true },
      usage: { include: true },
    }),
  });
  if (!response.ok) throw new Error(`Model provider returned HTTP ${response.status} for ${model}.`);
  const data = await response.json();
  if (data.error) throw new Error('Model provider could not complete the request.');
  const raw = decisions ? JSON.stringify(data.answers ?? {}) : data.choices?.[0]?.message?.content ?? '';
  let output = null;
  if (decisions) {
    const answer = data.answers?.decision;
    if (answer?.type === 'choice' && ['publish','hold'].includes(answer.choice)) output = {decision:answer.choice};
  } else if(options.outputType==='text') output=raw.trim() || null;
  else try { output = JSON.parse(raw); } catch { /* Invalid JSON is a scored failure. */ }
  const cost = data.usage?.cost;
  if (!Number.isFinite(cost) || cost < 0) throw new Error('Provider cost was missing; this run cannot support a cost comparison.');
  return { model, servedModel:data.model ?? model, provider: data.provider ?? null, generationId: data.id, output, raw,
    ...(!decisions?{finishReason:data.choices?.[0]?.finish_reason ?? null,reasoningTokens:data.usage?.completion_tokens_details?.reasoning_tokens ?? 0}:{}),
    ...(decisions ? {decision:data.answers?.decision ?? null} : {}),
    latencyMs: Math.round(performance.now() - start), cost,
    inputTokens: data.usage.input_tokens ?? data.usage.prompt_tokens, outputTokens: data.usage.output_tokens ?? data.usage.completion_tokens,
    measuredAt: new Date().toISOString() };
}
